/**
 * Builds the shipped character, "Tally", as an original glTF 2.0 binary.
 *
 *   node scripts/make-character-model.mjs
 *
 * Every vertex in the output is generated by the code below. Nothing is
 * downloaded, imported, traced or converted from anywhere: the geometry is
 * revolved and extruded from the profiles in DESIGN, the palette is chosen
 * here, and the six pose clips are keyframed here. That is the whole provenance
 * of `public/characters/tally/model.glb`, and it is why that one folder is the
 * only exception to the blanket ignore rule on public/characters.
 *
 * WHO TALLY IS
 * A small floating pod that keeps you company while you work. A wide dark
 * visor band across an egg-shaped shell, two amber eyes that are the only
 * things that really emote, two unattached mitts, a coral dorsal fin and a
 * crest with a bead on the end that droops when things are going badly. It has
 * no legs, no face beyond the eyes, and no mouth — everything it expresses, it
 * expresses with posture, which is what survives being drawn 48 pixels wide on
 * a dashboard.
 *
 * WHY IT IS BUILT RATHER THAN DRAWN
 * The repo's two existing mascots are hand-written SVG painted in theme tokens.
 * This is the third original character and the first rendered one, so the poses
 * are animation clips on one model rather than six separate images — the same
 * character in six states by construction, not by trying to draw it six times
 * consistently.
 *
 * No dependencies: a .glb is a 12-byte header, a JSON chunk and a binary chunk,
 * and node can write all three.
 */
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const OUT_DIR = join(dirname(fileURLToPath(import.meta.url)), '..', 'public', 'characters', 'tally');

// ---------------------------------------------------------------------------
// Colour. glTF factors are LINEAR, not sRGB — handing it a hex triple directly
// is the classic way to get a washed-out model.
// ---------------------------------------------------------------------------
const srgbToLinear = (c) => (c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4);

function linearRGBA(hex, alpha = 1) {
  const h = hex.replace('#', '');
  const channels = [0, 2, 4].map((i) => parseInt(h.slice(i, i + 2), 16) / 255);
  return [...channels.map(srgbToLinear), alpha];
}

/**
 * The palette, invented for this character.
 *
 * Mid-tone on purpose: the figure sits directly on a themed surface with no
 * card behind it, and those surfaces run from #fcfcfb to #0d0d0d across the six
 * skin/mode combinations. A pale character would vanish in light mode and a
 * dark one in dark mode, so the shell is a slate teal that silhouettes against
 * both, with warm coral and amber for the two small things that need to catch
 * the eye.
 */
const PALETTE = {
  shell: '#5e8494',
  shellLight: '#7a9daa',
  shellDark: '#3e5c6b',
  visor: '#1b242b',
  eye: '#ffd27a',
  coral: '#e8734a',
};

const MATERIALS = [
  { name: 'shell', pbrMetallicRoughness: { baseColorFactor: linearRGBA(PALETTE.shell), metallicFactor: 0.08, roughnessFactor: 0.62 } },
  // The mitts are a shade lighter than the shell for one reason: at 48px they
  // sit directly against the body's silhouette, and in the same colour they
  // disappeared into it.
  { name: 'shellLight', pbrMetallicRoughness: { baseColorFactor: linearRGBA(PALETTE.shellLight), metallicFactor: 0.08, roughnessFactor: 0.6 } },
  { name: 'shellDark', pbrMetallicRoughness: { baseColorFactor: linearRGBA(PALETTE.shellDark), metallicFactor: 0.1, roughnessFactor: 0.55 } },
  { name: 'visor', pbrMetallicRoughness: { baseColorFactor: linearRGBA(PALETTE.visor), metallicFactor: 0.25, roughnessFactor: 0.18 } },
  {
    name: 'eye',
    pbrMetallicRoughness: { baseColorFactor: linearRGBA(PALETTE.eye), metallicFactor: 0, roughnessFactor: 0.35 },
    // The eyes are the only thing that emotes, so they carry their own light
    // and stay legible when the figure is backlit or very small.
    emissiveFactor: linearRGBA(PALETTE.eye).slice(0, 3).map((c) => c * 0.85),
  },
  { name: 'coral', pbrMetallicRoughness: { baseColorFactor: linearRGBA(PALETTE.coral), metallicFactor: 0.05, roughnessFactor: 0.5 } },
];
const MAT = Object.fromEntries(MATERIALS.map((m, i) => [m.name, i]));

// ---------------------------------------------------------------------------
// Geometry. Two builders cover the whole character: revolve a profile, or
// extrude a polygon.
// ---------------------------------------------------------------------------

/** Revolve a profile of [radius, height] pairs around Y. */
function lathe(profile, segments = 40) {
  const positions = [];
  const indices = [];
  for (let s = 0; s <= segments; s++) {
    const a = (s / segments) * Math.PI * 2;
    const cos = Math.cos(a);
    const sin = Math.sin(a);
    for (const [r, y] of profile) positions.push(r * cos, y, -r * sin);
  }
  const rows = profile.length;
  for (let s = 0; s < segments; s++) {
    for (let i = 0; i < rows - 1; i++) {
      const a = s * rows + i;
      const b = (s + 1) * rows + i;
      indices.push(a, a + 1, b + 1, a, b + 1, b);
    }
  }
  return smooth({ positions, indices });
}

const sphere = (r, segments = 32, rings = 20) =>
  lathe(
    Array.from({ length: rings + 1 }, (_, i) => {
      const t = (i / rings) * Math.PI;
      return [Math.sin(t) * r, Math.cos(t) * r * -1];
    }),
    segments,
  );

/** Area-weighted vertex normals, for anything that should read as curved. */
function smooth({ positions, indices }) {
  const normals = new Array(positions.length).fill(0);
  for (let i = 0; i < indices.length; i += 3) {
    const [a, b, c] = [indices[i], indices[i + 1], indices[i + 2]];
    const n = faceNormal(positions, a, b, c);
    if (!n) continue;
    for (const v of [a, b, c]) {
      normals[v * 3] += n[0];
      normals[v * 3 + 1] += n[1];
      normals[v * 3 + 2] += n[2];
    }
  }
  for (let v = 0; v < normals.length; v += 3) {
    const len = Math.hypot(normals[v], normals[v + 1], normals[v + 2]);
    // A degenerate ring at a lathe pole contributes nothing; point it up
    // rather than leaving a NaN in the buffer.
    if (len < 1e-9) normals[v + 1] = 1;
    else {
      normals[v] /= len;
      normals[v + 1] /= len;
      normals[v + 2] /= len;
    }
  }
  return { positions, normals, indices };
}

function faceNormal(positions, a, b, c) {
  const at = (i) => [positions[i * 3], positions[i * 3 + 1], positions[i * 3 + 2]];
  const [ax, ay, az] = at(a);
  const [bx, by, bz] = at(b);
  const [cx, cy, cz] = at(c);
  const u = [bx - ax, by - ay, bz - az];
  const v = [cx - ax, cy - ay, cz - az];
  const n = [u[1] * v[2] - u[2] * v[1], u[2] * v[0] - u[0] * v[2], u[0] * v[1] - u[1] * v[0]];
  return Math.hypot(...n) < 1e-12 ? null : n;
}

// ---------------------------------------------------------------------------
// The character itself.
// ---------------------------------------------------------------------------

/** An egg, widest below the middle, so it reads as settled rather than balloon-like. */
const BODY_PROFILE = [
  [0.0, -0.5],
  [0.15, -0.485],
  [0.28, -0.44],
  [0.37, -0.36],
  [0.425, -0.25],
  [0.45, -0.12],
  [0.448, 0.0],
  [0.425, 0.12],
  [0.385, 0.23],
  [0.33, 0.325],
  [0.262, 0.4],
  [0.18, 0.455],
  [0.092, 0.49],
  [0.0, 0.505],
];

/**
 * The radius of the body at a given height, by walking BODY_PROFILE.
 *
 * The collar below is built from this rather than from its own hand-typed
 * numbers, so it hugs the shell by a constant margin all the way round instead
 * of sinking into it at one end and floating off it at the other.
 */
function bodyRadiusAt(y) {
  for (let i = 0; i < BODY_PROFILE.length - 1; i++) {
    const [r0, y0] = BODY_PROFILE[i];
    const [r1, y1] = BODY_PROFILE[i + 1];
    if (y >= y0 && y <= y1) return r0 + ((r1 - r0) * (y - y0)) / (y1 - y0);
  }
  return 0;
}

/**
 * A band around the lower shell.
 *
 * This replaces the dorsal fin the first pass had. The fin was correct
 * geometry in the wrong place: dead centre behind a body wider than it was, so
 * from the front — which is the only angle this character is ever drawn from —
 * it was completely hidden, and it was paying for three hundred triangles to
 * be invisible. A collar reads head-on, breaks the egg silhouette, and gives
 * the front of the figure its second colour.
 */
function collarProfile(from, to, margin, steps = 8) {
  return Array.from({ length: steps + 1 }, (_, i) => {
    const y = from + ((to - from) * i) / steps;
    // Held proud across the middle and tapered only at the two ends, so it
    // reads as a band rather than as a faint bulge. A plain sine taper peaked
    // for one ring and was barely visible against the shell.
    const t = Math.min(1, Math.sin((i / steps) * Math.PI) * 1.9);
    return [bodyRadiusAt(y) + margin * t, y];
  });
}

/** A tapered stalk for the crest. */
const CREST_PROFILE = [
  [0.0, 0.0],
  [0.03, 0.01],
  [0.024, 0.09],
  [0.016, 0.17],
  [0.0, 0.19],
];

/**
 * Segment counts are chosen for the sizes this is actually drawn at — between
 * 36 and 112 pixels — not for a close-up. Halving them from the first pass
 * took the file from 113 KB to well under that and is invisible at any size
 * the app uses.
 */
const MESHES = {
  body: { geometry: lathe(BODY_PROFILE, 32), material: MAT.shell },
  collar: { geometry: lathe(collarProfile(-0.4, -0.06, 0.055, 12), 32), material: MAT.coral },
  visor: { geometry: sphere(0.4, 30, 18), material: MAT.visor },
  eye: { geometry: sphere(0.062, 16, 10), material: MAT.eye },
  crest: { geometry: lathe(CREST_PROFILE, 12), material: MAT.shellDark },
  bead: { geometry: sphere(0.058, 16, 10), material: MAT.coral },
  hand: { geometry: sphere(0.12, 20, 12), material: MAT.shellLight },
};

/**
 * The node graph.
 *
 * `root` carries the whole figure, so bobbing and spinning it moves everything
 * together. The eyes hang off `body` rather than off `visor`, because the visor
 * is a sphere squashed to 40% height and the eyes would inherit that squash —
 * which would make a blink impossible to keyframe cleanly.
 */
const NODES = [
  { name: 'root', children: ['body', 'handL', 'handR'] },
  { name: 'body', mesh: 'body', children: ['collar', 'visor', 'eyeL', 'eyeR', 'crest'] },
  { name: 'collar', mesh: 'collar' },
  { name: 'visor', mesh: 'visor', translation: [0, 0.24, 0], scale: [1.02, 0.4, 1.02] },
  { name: 'eyeL', mesh: 'eye', translation: [-0.135, 0.26, 0.35], scale: [1, 1, 0.55] },
  { name: 'eyeR', mesh: 'eye', translation: [0.135, 0.26, 0.35], scale: [1, 1, 0.55] },
  { name: 'crest', mesh: 'crest', translation: [0, 0.49, -0.015], children: ['bead'] },
  { name: 'bead', mesh: 'bead', translation: [0, 0.2, 0] },
  { name: 'handL', mesh: 'hand', translation: [-0.54, -0.1, 0.12], scale: [1, 0.85, 0.9] },
  { name: 'handR', mesh: 'hand', translation: [0.54, -0.1, 0.12], scale: [1, 0.85, 0.9] },
];

// ---------------------------------------------------------------------------
// Poses, as animation clips.
//
// Everything Tally expresses is posture, because posture is what survives at
// 48 pixels: how high it floats, how far the crest has drooped, where the mitts
// are, and how open the eyes are. Nothing here relies on a detail you would
// need to zoom in to see.
// ---------------------------------------------------------------------------
const DEG = Math.PI / 180;

/** three.js's default XYZ Euler order, so the clips read the same in-engine. */
function quat([rx, ry, rz]) {
  const [x, y, z] = [rx * DEG * 0.5, ry * DEG * 0.5, rz * DEG * 0.5];
  const [c1, c2, c3] = [Math.cos(x), Math.cos(y), Math.cos(z)];
  const [s1, s2, s3] = [Math.sin(x), Math.sin(y), Math.sin(z)];
  return [
    s1 * c2 * c3 + c1 * s2 * s3,
    c1 * s2 * c3 - s1 * c2 * s3,
    c1 * c2 * s3 + s1 * s2 * c3,
    c1 * c2 * c3 - s1 * s2 * s3,
  ];
}

const track = (node, path, times, values) => ({ node, path, times, values });
const spin = (node, times, eulers) => track(node, 'rotation', times, eulers.map(quat));
/** The same track for both mitts, with X mirrored. */
const bothHands = (times, values) => [
  track('handL', 'translation', times, values.map(([x, y, z]) => [-x, y, z])),
  track('handR', 'translation', times, values),
];
const bothEyes = (times, values) => [
  track('eyeL', 'scale', times, values),
  track('eyeR', 'scale', times, values),
];

const CLIPS = [
  {
    // Resting. A slow float, a crest that sways, and a blink late in the loop
    // so two figures on one screen do not blink in lockstep for long.
    name: 'idle',
    tracks: [
      track('root', 'translation', [0, 1.6, 3.2], [[0, 0, 0], [0, 0.045, 0], [0, 0, 0]]),
      track('body', 'scale', [0, 0.8, 2.4, 3.2], [[1, 1, 1], [1.02, 0.978, 1.02], [0.986, 1.016, 0.986], [1, 1, 1]]),
      ...bothHands([0, 1.6, 3.2], [[0.54, -0.1, 0.12], [0.555, -0.065, 0.12], [0.54, -0.1, 0.12]]),
      spin('crest', [0, 0.8, 1.6, 2.4, 3.2], [[0, 0, 0], [0, 0, -7], [0, 0, 0], [0, 0, 7], [0, 0, 0]]),
      ...bothEyes(
        [0, 2.4, 2.48, 2.56, 3.2],
        [[1, 1, 0.55], [1, 1, 0.55], [1, 0.12, 0.55], [1, 1, 0.55], [1, 1, 0.55]],
      ),
    ],
  },
  {
    // One ticked question. Deliberately the same beat as the jsJump keyframes
    // in globals.css — anticipation, launch, hang, squash on landing — so the
    // rendered character and the SVG mascots celebrate in the same rhythm.
    name: 'celebrate',
    tracks: [
      track('root', 'translation', [0, 0.126, 0.342, 0.522, 0.72, 0.9],
        [[0, 0, 0], [0, -0.035, 0], [0, 0.36, 0], [0, 0.4, 0], [0, 0.018, 0], [0, 0, 0]]),
      track('body', 'scale', [0, 0.126, 0.342, 0.522, 0.72, 0.9],
        [[1, 1, 1], [1.07, 0.92, 1.07], [0.94, 1.09, 0.94], [1, 1, 1], [1.09, 0.9, 1.09], [1, 1, 1]]),
      ...bothHands([0, 0.126, 0.342, 0.522, 0.72, 0.9],
        [[0.54, -0.1, 0.12], [0.52, -0.14, 0.12], [0.6, 0.14, 0.08], [0.62, 0.2, 0.06], [0.54, -0.13, 0.12], [0.54, -0.1, 0.12]]),
      spin('crest', [0, 0.126, 0.342, 0.522, 0.72, 0.9],
        [[0, 0, 0], [0, 0, 11], [0, 0, -15], [0, 0, -9], [0, 0, 13], [0, 0, 0]]),
      track('bead', 'translation', [0, 0.126, 0.342, 0.522, 0.72, 0.9],
        [[0, 0.2, 0], [0, 0.186, 0], [0, 0.229, 0], [0, 0.235, 0], [0, 0.185, 0], [0, 0.2, 0]]),
      ...bothEyes([0, 0.342, 0.522, 0.9], [[1, 1, 0.55], [1, 0.6, 0.55], [1, 0.6, 0.55], [1, 1, 0.55]]),
    ],
  },
  {
    // A finished heading or section: the same jump, higher, with a full turn.
    // Four 90-degree keys rather than one 360, because a rotation track
    // interpolates the short way round and would otherwise not turn at all.
    name: 'milestone',
    tracks: [
      track('root', 'translation', [0, 0.18, 0.45, 0.75, 1.05, 1.3, 1.5],
        [[0, 0, 0], [0, -0.05, 0], [0, 0.42, 0], [0, 0.46, 0], [0, 0.4, 0], [0, 0.02, 0], [0, 0, 0]]),
      spin('root', [0, 0.18, 0.45, 0.75, 1.05, 1.3, 1.5],
        [[0, 0, 0], [0, 0, 0], [0, 90, 0], [0, 180, 0], [0, 270, 0], [0, 360, 0], [0, 360, 0]]),
      track('body', 'scale', [0, 0.18, 0.45, 0.75, 1.05, 1.3, 1.5],
        [[1, 1, 1], [1.09, 0.9, 1.09], [0.92, 1.12, 0.92], [1, 1, 1], [1, 1, 1], [1.11, 0.88, 1.11], [1, 1, 1]]),
      ...bothHands([0, 0.18, 0.45, 0.75, 1.05, 1.3, 1.5],
        [[0.54, -0.1, 0.12], [0.51, -0.16, 0.12], [0.64, 0.18, 0.06], [0.68, 0.26, 0.04], [0.64, 0.18, 0.06], [0.54, -0.15, 0.12], [0.54, -0.1, 0.12]]),
      ...bothEyes([0, 0.45, 1.05, 1.5], [[1, 1, 0.55], [1, 0.55, 0.55], [1, 0.55, 0.55], [1, 1, 0.55]]),
    ],
  },
  {
    // Coming back after a run has lapsed. Sunk, tipped forward, crest fully
    // down, mitts hanging. Gentle — it is meant to be recognised, not obeyed.
    name: 'sad',
    tracks: [
      track('root', 'translation', [0, 1.3, 2.6], [[0, -0.05, 0], [0, -0.085, 0], [0, -0.05, 0]]),
      spin('body', [0, 1.3, 2.6], [[9, 0, 0], [11, 0, 0], [9, 0, 0]]),
      spin('crest', [0, 1.3, 2.6], [[0, 0, -40], [0, 0, -47], [0, 0, -40]]),
      ...bothHands([0, 1.3, 2.6], [[0.5, -0.24, 0.08], [0.5, -0.27, 0.08], [0.5, -0.24, 0.08]]),
      ...bothEyes([0, 2.6], [[1, 0.42, 0.55], [1, 0.42, 0.55]]),
    ],
  },
  {
    // The softer one: nothing has broken, the pace has just dropped. A slow
    // head-tilt and a half-drooped crest — visibly not `sad`, and visibly not
    // fine either.
    name: 'concerned',
    tracks: [
      track('root', 'translation', [0, 1.5, 3.0], [[0, -0.01, 0], [0, 0.015, 0], [0, -0.01, 0]]),
      spin('root', [0, 0.75, 1.5, 2.25, 3.0], [[0, 0, 5], [0, 0, 0], [0, 0, -5], [0, 0, 0], [0, 0, 5]]),
      spin('crest', [0, 1.5, 3.0], [[0, 0, -20], [0, 0, -26], [0, 0, -20]]),
      ...bothHands([0, 1.5, 3.0], [[0.48, -0.12, 0.18], [0.48, -0.1, 0.2], [0.48, -0.12, 0.18]]),
      ...bothEyes([0, 3.0], [[1, 0.72, 0.55], [1, 0.72, 0.55]]),
    ],
  },
  {
    // A focus session is running. Almost still, eyes narrowed, mitts drawn in.
    // The one pose that means "right now" rather than "lately", so it has to
    // read as concentration rather than as either mood.
    name: 'focused',
    tracks: [
      track('root', 'translation', [0, 2.2, 4.4], [[0, 0, 0], [0, 0.02, 0], [0, 0, 0]]),
      spin('crest', [0, 1.1, 2.2, 3.3, 4.4], [[0, 0, 0], [0, 0, -5], [0, 0, 0], [0, 0, 5], [0, 0, 0]]),
      ...bothHands([0, 4.4], [[0.46, -0.12, 0.18], [0.46, -0.12, 0.18]]),
      ...bothEyes(
        [0, 3.4, 3.48, 3.56, 4.4],
        [[1, 0.6, 0.55], [1, 0.6, 0.55], [1, 0.12, 0.55], [1, 0.6, 0.55], [1, 0.6, 0.55]],
      ),
    ],
  },
];

// ---------------------------------------------------------------------------
// glTF 2.0 binary container.
// ---------------------------------------------------------------------------
const FLOAT = 5126;
const UNSIGNED_SHORT = 5123;
const ARRAY_BUFFER = 34962;
const ELEMENT_ARRAY_BUFFER = 34963;
const COMPONENTS = { SCALAR: 1, VEC3: 3, VEC4: 4 };

function buildGltf() {
  const chunks = [];
  let offset = 0;
  const bufferViews = [];
  const accessors = [];

  function view(typed, target) {
    const bytes = Buffer.from(typed.buffer, typed.byteOffset, typed.byteLength);
    const pad = (4 - (offset % 4)) % 4;
    if (pad) {
      chunks.push(Buffer.alloc(pad));
      offset += pad;
    }
    const v = { buffer: 0, byteOffset: offset, byteLength: bytes.length };
    if (target) v.target = target;
    bufferViews.push(v);
    chunks.push(bytes);
    offset += bytes.length;
    return bufferViews.length - 1;
  }

  /** `bounds` is required by the spec for POSITION and for animation inputs. */
  function accessor(typed, type, componentType, target, bounds = false) {
    const stride = COMPONENTS[type];
    const a = { bufferView: view(typed, target), componentType, count: typed.length / stride, type };
    if (bounds) {
      const min = new Array(stride).fill(Infinity);
      const max = new Array(stride).fill(-Infinity);
      for (let i = 0; i < typed.length; i++) {
        const c = i % stride;
        if (typed[i] < min[c]) min[c] = typed[i];
        if (typed[i] > max[c]) max[c] = typed[i];
      }
      a.min = min;
      a.max = max;
    }
    accessors.push(a);
    return accessors.length - 1;
  }

  const meshes = [];
  const meshIndex = {};
  for (const [name, { geometry, material }] of Object.entries(MESHES)) {
    const position = accessor(new Float32Array(geometry.positions), 'VEC3', FLOAT, ARRAY_BUFFER, true);
    const normal = accessor(new Float32Array(geometry.normals), 'VEC3', FLOAT, ARRAY_BUFFER);
    const indices = accessor(new Uint16Array(geometry.indices), 'SCALAR', UNSIGNED_SHORT, ELEMENT_ARRAY_BUFFER);
    meshIndex[name] = meshes.length;
    meshes.push({ name, primitives: [{ attributes: { POSITION: position, NORMAL: normal }, indices, material }] });
  }

  const nodeIndex = Object.fromEntries(NODES.map((n, i) => [n.name, i]));
  const nodes = NODES.map((n) => {
    const node = { name: n.name };
    if (n.mesh !== undefined) node.mesh = meshIndex[n.mesh];
    if (n.translation) node.translation = n.translation;
    if (n.scale) node.scale = n.scale;
    if (n.children) node.children = n.children.map((c) => nodeIndex[c]);
    return node;
  });

  const animations = CLIPS.map((clip) => {
    const samplers = [];
    const channels = [];
    for (const t of clip.tracks) {
      const type = t.path === 'rotation' ? 'VEC4' : 'VEC3';
      const input = accessor(new Float32Array(t.times), 'SCALAR', FLOAT, undefined, true);
      const output = accessor(new Float32Array(t.values.flat()), type, FLOAT);
      samplers.push({ input, output, interpolation: 'LINEAR' });
      channels.push({ sampler: samplers.length - 1, target: { node: nodeIndex[t.node], path: t.path } });
    }
    return { name: clip.name, samplers, channels };
  });

  const binary = Buffer.concat(chunks);
  const json = {
    asset: {
      version: '2.0',
      generator: 'job-switch-tracker scripts/make-character-model.mjs — original geometry, generated for this project',
      copyright: 'Original work, generated for this project.',
    },
    scene: 0,
    scenes: [{ nodes: [nodeIndex.root] }],
    nodes,
    meshes,
    materials: MATERIALS,
    accessors,
    bufferViews,
    buffers: [{ byteLength: binary.length }],
    animations,
  };
  return { json, binary };
}

/** 12-byte header, a JSON chunk padded with spaces, a BIN chunk padded with zeros. */
function toGlb({ json, binary }) {
  const pad = (buf, to, filler) => {
    const extra = (to - (buf.length % to)) % to;
    return extra ? Buffer.concat([buf, Buffer.alloc(extra, filler)]) : buf;
  };
  const jsonChunk = pad(Buffer.from(JSON.stringify(json), 'utf8'), 4, 0x20);
  const binChunk = pad(binary, 4, 0);

  const header = Buffer.alloc(12);
  header.writeUInt32LE(0x46546c67, 0); // "glTF"
  header.writeUInt32LE(2, 4);
  header.writeUInt32LE(12 + 8 + jsonChunk.length + 8 + binChunk.length, 8);

  const chunkHeader = (length, type) => {
    const b = Buffer.alloc(8);
    b.writeUInt32LE(length, 0);
    b.writeUInt32LE(type, 4);
    return b;
  };
  return Buffer.concat([
    header,
    chunkHeader(jsonChunk.length, 0x4e4f534a), // "JSON"
    jsonChunk,
    chunkHeader(binChunk.length, 0x004e4942), // "BIN\0"
    binChunk,
  ]);
}

/**
 * Attribution, written by the same script that writes the geometry so the two
 * cannot drift apart. `source` is omitted rather than filled in with something
 * plausible: there is no source, and a blank field is the honest answer.
 */
const META = {
  id: 'tally',
  name: 'Tally',
  artist: 'Generated for this project by scripts/make-character-model.mjs',
  license: 'Original work, generated for this project',
  lines: {
    cheer: ['Logged.', 'That one is behind you.', 'Counted.', 'Onward.'],
    milestone: ['Whole block, done.', 'That is the set.', 'All of them.'],
    idle: ['Still here.', 'One at a time.', 'Take the next one.', 'Whenever you are ready.'],
  },
};

const glb = toGlb(buildGltf());
mkdirSync(OUT_DIR, { recursive: true });
writeFileSync(join(OUT_DIR, 'model.glb'), glb);
writeFileSync(join(OUT_DIR, 'meta.json'), JSON.stringify(META, null, 2) + '\n');
console.log(`tally/model.glb  ${(glb.length / 1024).toFixed(1)} KB`);
console.log(`tally/meta.json  ${CLIPS.length} poses: ${CLIPS.map((c) => c.name).join(', ')}`);
